void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 g = uv * 12.0;
  float motif = sin(g.x * 6.0) * sin(g.y * 6.0);
  float bord = fwidth(motif) * 4.0;
  fragColor = vec4(abs(dFdx(motif)) * 8.0, abs(dFdy(motif)) * 8.0, clamp(bord, 0.0, 1.0), 1.0);
}
